"""Cleaning an export: prices carried forward, notes filled, text normalized."""

import pandas as pd
from pandas.api.types import is_string_dtype


def fill_prices(frame: pd.DataFrame) -> pd.DataFrame:
    """Carry the last known unit price forward into missing ones and recompute revenue."""
    frame = frame.copy()
    frame["unit_price"] = frame["unit_price"].ffill()
    frame["revenue"] = frame["units"] * frame["unit_price"]
    return frame


def fill_notes(frame: pd.DataFrame) -> pd.DataFrame:
    """Missing notes become empty strings."""
    frame = frame.copy()
    frame["notes"] = frame["notes"].fillna("")
    return frame


def normalize_text(frame: pd.DataFrame) -> pd.DataFrame:
    """Strip and title-case every text column."""
    frame = frame.copy()
    for column in frame.columns:
        if is_string_dtype(frame[column]):
            frame[column] = frame[column].str.strip().str.title()
    return frame


def round_prices(frame: pd.DataFrame, places: int = 2) -> pd.DataFrame:
    """Every float in the frame rounded to ``places``."""
    return frame.map(lambda value: round(value, places) if isinstance(value, float) else value)


def clean(frame: pd.DataFrame) -> pd.DataFrame:
    return normalize_text(fill_notes(fill_prices(frame)))

"""Money strings and printable tables."""

from typing import List

import pandas as pd


def format_money(value: float) -> str:
    return f"{value:,.2f}"


def format_table(frame: pd.DataFrame) -> str:
    """The frame as text, every float as money, without the index."""
    shown = frame.map(lambda value: format_money(value) if isinstance(value, float) else value)
    return shown.to_string(index=False)


def format_series(series: pd.Series) -> List[str]:
    """``"<index>: <money>"`` per entry."""
    return [f"{index}: {format_money(float(value))}" for index, value in series.items()]

"""Metrics over a cleaned export."""

import pandas as pd


def monthly_revenue(frame: pd.DataFrame) -> pd.Series:
    """Revenue per calendar month, indexed by month end."""
    return frame.set_index("date")["revenue"].resample("ME").sum()


def top_products(frame: pd.DataFrame, n: int = 3) -> pd.Series:
    """The ``n`` products with the most orders, most first."""
    return frame["product"].value_counts().head(n)


def first_week(frame: pd.DataFrame) -> pd.DataFrame:
    """The orders of the first seven days, indexed by date."""
    indexed = frame.set_index("date").sort_index()
    if indexed.empty:
        return indexed
    return indexed.loc[indexed.index < indexed.index[0] + pd.Timedelta(days=7)]


def regional_share(frame: pd.DataFrame) -> pd.Series:
    """Each region's share of total revenue, indexed by region."""
    totals = frame.groupby("region")["revenue"].sum().astype(float)
    shares = totals / totals.sum()
    shares.index = totals.index.tolist()
    return shares.astype(float)


def average_order(frame: pd.DataFrame) -> float:
    return float(frame["revenue"].mean())


def units_by_product(frame: pd.DataFrame) -> pd.Series:
    """Units per product, most first."""
    return frame.groupby("product")["units"].sum().sort_values(ascending=False)
